.option-label {
  font-size: 1rem;
  user-select: none;
}

.actions {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
}

.btn {
  font: inherit;
  font-weight: 600;
  padding: 10px 20px;
  min-height: 44px;
  border-radius: 8px;
