+              key={opt.value}
+              id={`${baseId}-${opt.value}`}
+              name="notification-preference"
+              value={opt.value}
+              label={opt.label}
+              checked={value === opt.value}
+              onChange={(e) => onChange(e.target.value)}
+              required
+            />
+          ))}
+        </div>
+      </fieldset>
+    </div>
+  );
+}
+
+function NotificationForm() {
+  const [preference, setPreference] = useState("");
+  const [status, setStatus] = useState("");
+  const statusRef = useRef(null);
+
+  const handleSubmit = (e) => {
+    e.preventDefault();
+    if (!preference) {
+      setStatus("Please select a notification preference to continue.");
+      return;
+    }
+    const labels = { email: "Email", sms: "SMS", push: "Push Notifications" };
+    setStatus(`Preference saved: ${labels[preference]}.`);
+  };
+
+  return (
+    <form noValidate onSubmit={handleSubmit}>
+      <NotificationPreferenceField value={preference} onChange={setPreference} />
