+      <div
+        ref={statusRef}
+        className="status"
+        role="status"
+        aria-live="polite"
+        aria-atomic="true"
+      >
+        {status}
+      </div>
+    </form>
+  );
+}
+
+function App() {
+  return (
+    <>
+      <a href="#main" className="skip-link">Skip to main content</a>
