const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const file = 'file://' + path.resolve(process.argv[2]);
  const errors = [];
  page.on('pageerror', e => errors.push(String(e)));
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  await page.goto(file, { waitUntil: 'load' });
  // Wait for React to render
  await page.waitForSelector('fieldset', { timeout: 10000 });
  await page.addScriptTag({ path: '/tmp/axe.min.js' });
  const r = await page.evaluate(async () => await window.axe.run());
  await browser.close();
  const wcag = r.violations.filter(v => !v.tags.includes('best-practice'));
  const bp = r.violations.filter(v => v.tags.includes('best-practice'));
  console.log(JSON.stringify({
    pageErrors: errors,
    wcag: wcag.map(v => ({ id: v.id, impact: v.impact, help: v.help, targets: v.nodes.map(n => n.target) })),
    bp: bp.map(v => ({ id: v.id, help: v.help, targets: v.nodes.map(n => n.target) })),
  }, null, 2));
  process.exit(wcag.length ? 1 : 0);
})();

